function settingsView(){return `${head('Settings & Project Backup','Control theme, local media access and recoverable projects.')}
 <div class="grid2"><div class="panel stack"><h3>Appearance</h3><select id="themeSetting">${options(['dark','light'],mode)}</select><h3>Project</h3><div class="field"><label>Name</label><input data-field="name" value="${attr(p.name)}"/></div><div class="field"><label>Resolution</label><select data-field="ratio">${options(['9:16','16:9','1:1','4:5'],p.ratio)}</select></div><div class="field"><label>Duration</label><input type="number" min="1" data-field="duration" value="${p.duration}"/></div><div class="rowgap"><button class="btn secondary" data-action="project-json">Export JSON</button><label class="btn">Import Project JSON<input type="file" class="hide" accept="application/json,.json" data-ingest="project"/></label></div></div><div class="panel stack"><h3>Real Capability Matrix</h3>${[['Adaptive dark/light UI','Working'],['Multitrack timeline editing','Working'],['Asset prompts/uploads/host','Working'],['Flow clip join (re-encode)','Platform-dependent'],['MP4 output','Only if codec supported'],['Whisper Tiny ASR','Experimental · first model download'],['Word-level Whisper time alignment','Pending'],['Noise reduction and 4K upscaling','Pending'],['Advanced GPU mask and tracking','Pending'],['Fully offline LLM director','Pending']].map(([n,s])=>`<div class="between"><span>${n}</span><span class="pill ${s==='Working'?'green':''}">${s}</span></div>`).join('')}</div></div>`;}
function applyPlanner(){snapshot();p.clips=timelineFromShots(shots,p.assets);p.duration=Math.max(1,...shots.map(s=>s.end));selectedClipId=p.clips[0]?.id||null;store();setPage('editor');notify(`${p.clips.length} editable timeline clips created from ${shots.length} shots.`);}
function copy(text){if(navigator.clipboard?.writeText){navigator.clipboard.writeText(String(text)).then(()=>notify('Copied to clipboard')).catch(()=>fallbackCopy(text));}else fallbackCopy(text);}
function fallbackCopy(value){const t=document.createElement('textarea');t.value=value;document.body.append(t);t.select();document.execCommand('copy');t.remove();notify('Copied');}
function exportText(text,name,type='text/plain'){downloadData(new Blob([text],{type}),name);}
async function ingestFile(file){if(!file)return null;const m=engine||flowEngine||new MediaEngine(document.createElement('canvas'));if(!m.project)m.project=p;const id=await m.ingest(file);
 if(file.type.startsWith('video/')||file.type.startsWith('audio/')){try{const el=document.createElement(file.type.startsWith('audio/')?'audio':'video');el.preload='metadata';const url=URL.createObjectURL(file);let duration=await new Promise((res,rej)=>{el.onloadedmetadata=()=>res(el.duration);el.onerror=()=>rej(new Error('Metadata unavailable'));el.src=url;setTimeout(()=>res(null),8000);});URL.revokeObjectURL(url);if(Number.isFinite(duration)&&duration>0)p.media[id].duration=duration;}catch{}}
 store();return id;}
async function onFiles(input){const files=[...input.files];if(!files.length)return;const op=input.dataset.ingest;try{
 if(op==='srt'){const t=await files[0].text();snapshot();p.transcript=parseSrt(t);notify(`${p.transcript.length} timed cues imported`);store();render();return;}
 if(op==='project'){const proj=JSON.parse(await files[0].text());if(!Array.isArray(proj.clips)||!proj.media)throw Error('Invalid project file');snapshot();p=clampProject(proj);shots=p.shots||chocolateShots();store();render();notify('Project JSON restored. Relink media files if not on this device.');return;}
 snapshot();let ids=[];for(const f of files){ids.push(await ingestFile(f));}
 if(op==='library'){notify(`${ids.length} media files imported`);}
 else if(op==='whisper'){selectedMediaId=ids[0];notify('Audio source imported for Whisper');}
 else if(op==='slot'){p.assets[+input.dataset.index].mediaId=ids[0];}
 else if(op==='host'){const a=p.assets[+input.dataset.index];a.hostMediaId=ids[0];a.hostEnabled=true;}
 else if(op==='extra'){const ex=p.assets[+input.dataset.index].extras[+input.dataset.extra];ex.mediaId=ids[0];ex.enabled=true;}
 else if(op==='overlay'){const a=p.assets[+input.dataset.index],o=input.dataset.scope==='primary'?a.overlays[+input.dataset.overlay]:a.extras[+input.dataset.extra].overlays[+input.dataset.overlay];o.mediaId=ids[0];o.enabled=true;}
 else if(op==='flow'){for(const id of ids)p.flow.push({id:uid('flow'),mediaId:id,duration:p.media[id].duration||8});notify(`${ids.length} clips added to Flow Studio`);}
 store();render();
 }catch(e){notify('Import failed: '+e.message);console.error(e);}}
function showExportDialog(context='editor'){if(jobBusy)return notify('Export already in progress');let count=context==='flow'?p.flow.length:p.clips.length, missing=context==='flow'?p.flow.filter(f=>!p.media[f.mediaId]).length:p.clips.filter(c=>c.kind==='video'&&!c.mediaId).length;
 const dialog=document.createElement('dialog');dialog.id='exportDialog';dialog.innerHTML=`<div class="modal-pad stack"><div class="between"><h2 class="mb0">Export ${context==='flow'?'Flow Sequence':'Edited Video'}</h2><button class="icon-button" id="closeExport">×</button></div><div class="field"><label>Video resolution</label><select id="exportSize">${options(['720p','1080p'],'720p')}</select></div><div class="field"><label>Actual supported container</label><input readonly value="${attr(probeRecordFormat()||'Not available')}"/></div><div class="hint">A ${context==='flow'?'Flow clip sequence':'multitrack composition'} of ${count} clips will render in real time on your device. ${missing?`${missing} video clips have no source media. Placeholder frames may be visible.`:'Visual media appears attached to each base clip.'}</div><div class="rowgap"><button id="startExport" class="btn primary grow">Start Rendering</button><button class="btn" id="cancelExport" disabled>Cancel</button></div><div class="meter"><span id="exportMeter" style="width:0%"></span></div><div class="small" id="exportStatus">Ready · Encoding happens locally. Keep this window open.</div></div>`;document.body.append(dialog);dialog.showModal();const stop=()=>{if(!jobBusy){dialog.close();dialog.remove();}};dialog.querySelector('#closeExport').onclick=stop;dialog.querySelector('#cancelExport').onclick=()=>{(context==='flow'?flowEngine:engine)?.abortExport();};dialog.querySelector('#startExport').onclick=async()=>{const m=context==='flow'?flowEngine:engine;if(!m)return notify('Preview renderer is not available');if(missing&&!confirm(`There are ${missing} missing visual clips. Export placeholders anyway?`))return;
 jobBusy=true;dialog.querySelector('#startExport').disabled=true;dialog.querySelector('#cancelExport').disabled=false;const status=dialog.querySelector('#exportStatus');status.textContent='Rendering and encoding…';m.onProgress=x=>{dialog.querySelector('#exportMeter').style.width=x+'%';status.textContent=`Rendering ${x}% — ${timestamp(m.t)} / ${timestamp(m.project.duration)}`;};try{const result=await m.export({resolution:dialog.querySelector('#exportSize').value});const filename=`${context==='flow'?'Flow_':'CineZehn_'}${p.name.replace(/[^\w-]/g,'_')}.${result.ext}`;downloadData(result.blob,filename);status.textContent=`Export ready: ${filename} (${(result.blob.size/1024/1024).toFixed(1)} MB). Check Downloads.`;notify(`Export complete · ${result.ext.toUpperCase()}`);}catch(e){status.textContent=e.message;notify('Export: '+e.message);}finally{jobBusy=false;dialog.querySelector('#cancelExport').disabled=true;dialog.querySelector('#startExport').disabled=false;}};}
function renderGraphicPNG(type='Pointer Arrow',label='STEP 01',color='#ffd735'){const canvas=document.createElement('canvas');canvas.width=512;canvas.height=512;const g=canvas.getContext('2d');g.strokeStyle=color;g.fillStyle=color;g.lineCap='round';g.lineJoin='round';g.lineWidth=22;
 if(type==='Pointer Arrow'){g.beginPath();g.moveTo(80,370);g.lineTo(350,130);g.moveTo(226,132);g.lineTo(353,130);g.lineTo(343,257);g.stroke();}
 else if(type==='Circle Highlight'){g.beginPath();g.ellipse(256,256,180,156,-.15,0,Math.PI*2);g.stroke();}
 else if(type==='Lower Third'){g.fillRect(32,310,448,125);g.fillStyle='#181421';g.font='bold 54px system-ui';g.fillText(label.slice(0,12),50,391);}
 else if(type==='Step Number'){g.beginPath();g.arc(256,256,185,0,Math.PI*2);g.stroke();g.textAlign='center';g.textBaseline='middle';g.font='900 105px system-ui';g.fillText(label.slice(0,7),256,256);}
 else if(type==='Progress Ring'){g.beginPath();g.arc(256,256,150,Math.PI*.7,Math.PI*2.1);g.stroke();}
 else{g.fillRect(45,190,422,125);g.fillStyle='#161025';g.font='900 48px system-ui';g.textAlign='center';g.fillText(label.slice(0,13),256,268);}
 return canvas;}
async function runWhisper(){const id=$('#whisperMedia')?.value||selectedMediaId;if(!id)return notify('Import and select an audio/video file first');const blob=await getBlob(id);if(!blob)return notify('Source media is missing. Relink the file.');selectedMediaId=id;const lang=$('#whisperLang').value;sessionStorage.setItem('whisper_lang',lang);const status=$('#whisperStatus');const btn=$('[data-action="whisper-run"]');btn.disabled=true;try{const result=await whisperTranscribe(blob,{language:lang,onStatus:s=>{status.textContent=s;}});snapshot();p.transcript=result.cues;store();notify(`${result.cues.length} Whisper cues generated`);render();}catch(e){status.textContent=e.message;notify(e.message);btn.disabled=false;}}
function buildTranscriptChatGPT(){let source=p.transcript.map(c=>`[${timestamp(c.start)}–${timestamp(c.end)}] ${c.text}`).join('\n');return `CINEZEHN AI STUDIO PRO — TIMECODED EDIT REQUEST\nRatio: ${p.ratio}\nDuration: ${timestamp(p.duration)}\nStyle: ${p.style}\n\nBelow is the approved transcript. Generate a timestamped fast-paced edit plan that my CineZehn Auto Planner can parse. Use SCENE headings and subshot ranges, and explicit VISUAL:, MOTION:, GRAPHICS:, SFX:, BGM:, TRANSITION: lines. Align edits to actual words. Create visual prompts for each named scene. Do not invent claims or fabricate footage.\n\nTRANSCRIPT:\n${source}`;}
function slotSet(el,value){const i=+el.dataset.index,a=p.assets[i];if(!a)return;
 if(el.dataset.slotPrompt!==undefined)a.prompt=value;
 if(el.dataset.slotField)a[el.dataset.slotField]=value;
 if(el.dataset.slotToggle)a[el.dataset.slotToggle]=!!value;
 if(el.dataset.extraToggle!==undefined)a.extras[+el.dataset.extraToggle].enabled=!!value;
 if(el.dataset.extraPrompt!==undefined)a.extras[+el.dataset.extraPrompt].prompt=value;
 if(el.dataset.extraMotion!==undefined)a.extras[+el.dataset.extraMotion].motion=value;
 const ovId=el.dataset.overlayToggle??el.dataset.overlayPrompt??el.dataset.overlayMotion;
 if(ovId!==undefined){const o=el.dataset.scope==='primary'?a.overlays[+ovId]:a.extras[+el.dataset.extra].overlays[+ovId];if(el.dataset.overlayToggle!==undefined)o.enabled=!!value;if(el.dataset.overlayPrompt!==undefined)o.prompt=value;if(el.dataset.overlayMotion!==undefined)o.motion=value;}
 store();}
const boolAttr=new Set(['hostEnabled','muted']);
function updateClip(el){const c=currentClip();if(!c)return;const key=el.dataset.clip;let val=el.type==='checkbox'?el.checked:el.value;if(['start','duration','srcIn','x','y','scale','opacity','rotation','speed','volume','fontSize'].includes(key)){val=Number(val);if(!Number.isFinite(val))return;if(key==='start')val=clamp(val,0,p.duration);if(key==='duration')val=clamp(val,.1,36000);}if(key==='track')val=+val;snapshot();c[key]=val;store();const t=engine?.t||0;render();engine?.seek(t);}
function addMediaClip(id){const m=p.media[id];if(!m)return;let type=m.type.startsWith('audio')?'audio':m.type.startsWith('video')?'video':'overlay';snapshot();const st=Math.min(engine?.t||0,p.duration-.1),len=Math.min(p.duration-st,m.duration||5);const c=clip(type,st,Math.max(.1,len),id,{name:m.name,track:type==='audio'?6:type==='video'?0:1,motion:type==='video'?'Slow Push':'Float'});p.clips.push(c);selectedClipId=c.id;store();render();notify(`Media added on ${trackInfo[c.track][0]} track`);}
function bindActions(){document.body.addEventListener('click',async e=>{const button=e.target.closest('[data-action]');if(!button)return;const a=button.dataset.action,v=button.dataset.value;try{switch(a){
 case 'page':setPage(v);break;case 'go-whisper':setPage('whisper');break;
 case 'chocolate':case 'use-chocolate':{snapshot();shots=chocolateShots();p.name='Chocolate Factory';p.duration=60;p.assetCount=20;p.assets=slotsFromShots(shots,20,p.ratio,p.assets);p.clips=timelineFromShots(shots,p.assets);store();render();notify('Chocolate Factory: 27 shots, 20 slots');break;}
 case 'director-generate':makeDirectorDraft();break;case 'director-to-planner':p.masterPrompt=$('#directorOutput').value;p.name=sessionStorage.getItem('director_topic')||p.name;store();setPage('planner');break;case 'copy-director':copy($('#directorOutput').value);break;
 case 'parse-prompt':{p.masterPrompt=$('#masterPrompt').value;const {shots:parsed,warnings}=parseEditBrief(p.masterPrompt);if(!parsed.length){notify('No valid shot ranges found. Use e.g. 00:00–00:02 with VISUAL:');break;}snapshot();shots=parsed;p.duration=Math.max(...parsed.map(s=>s.end));p.assets=slotsFromShots(shots,p.assetCount,p.ratio,p.assets);store();render();notify(`${shots.length} shots parsed. ${warnings.length?warnings.join(' • '):'No time overlap warnings.'}`);break;}
 case 'build-slots':{const c=$('#planCount').value;const n=c==='Custom'?Number($('#customCount').value):Number(c);if(n<1||n>100)return notify('Choose 1–100 primary assets');snapshot();p.assetCount=n;p.assets=slotsFromShots(shots,n,p.ratio,p.assets);store();render();notify(`${n} separate prompts + upload boxes created`);break;}
 case 'copy-slot':copy(p.assets[+v]?.prompt||'');break;case 'slot-focus':selectedSlot=+v;render();document.getElementById(`slot_${v}`)?.scrollIntoView({behavior:'instant',block:'center'});break;
 case 'planner-to-editor':applyPlanner();break;case 'export-cues':exportText(JSON.stringify({schemaVersion:1,project:p.name,ratio:p.ratio,shots,assets:p.assets.map(x=>({id:x.id,start:x.start,end:x.end,prompt:x.prompt,mediaId:x.mediaId}))},null,2),'CineZehn_Cue_Sheet.json','application/json');break;
 case 'paste-clipboard':try{const text=await navigator.clipboard.readText();$('#masterPrompt').value=text;p.masterPrompt=text;store();notify('Pasted editing brief');}catch{notify('Use long-press → Paste in this input');}break;
 case 'play':if(!engine)return;if(engine.playing){engine.pause();button.textContent='▶';}else{await engine.play();button.textContent='Ⅱ';}break;
 case 'seek-begin':engine?.seek(0);break;
 case 'split':{const c=currentClip(),t=engine?.t||0;if(!c||t<=c.start+.05||t>=c.start+c.duration-.05)return notify('Select a clip and put playhead inside it');snapshot();let next={...c,id:uid('clip'),start:t,duration:c.start+c.duration-t,srcIn:(c.srcIn||0)+(t-c.start)*(c.speed||1)};c.duration=t-c.start;p.clips.push(next);selectedClipId=next.id;store();render();notify('Clip split non-destructively');break;}
 case 'duplicate':{const c=currentClip();if(!c)return; snapshot();const next={...c,id:uid('clip'),start:clamp(c.start+c.duration,0,36000)};p.clips.push(next);p.duration=Math.max(p.duration,next.start+next.duration);selectedClipId=next.id;store();render();break;}
 case 'delete-clip':{const c=currentClip();if(!c)return;snapshot();p.clips=p.clips.filter(x=>x.id!==c.id);selectedClipId=null;store();render();break;}
 case 'add-text':case 'add-graphic':{snapshot();const kind=a==='add-text'?'caption':'text';const c=clip(kind,Math.min(engine?.t||0,p.duration-.2),3,null,{name:a==='add-text'?'New Caption':'Graphic Label',text:a==='add-text'?'Your caption':'STEP 01',track:kind==='caption'?3:4,style:'Pop Bold'});p.clips.push(c);selectedClipId=c.id;store();render();break;}
 case 'import-audio':{setPage('editor');const el=document.querySelector('input[data-ingest="library"]');el?.click();break;}
 case 'replace-media':{const f=document.createElement('input');f.type='file';f.accept='image/*,video/*,audio/*';f.onchange=async()=>{const file=f.files?.[0];if(file){const id=await ingestFile(file);currentClip().mediaId=id;store();render();notify('Clip source replaced');}};f.click();break;}
 case 'add-media-clip':addMediaClip(v);break;case 'undo':undo();break;case 'redo':redo();break;case 'open-export':showExportDialog('editor');break;
 case 'flow-up':case 'flow-down':{const i=+v,j=i+(a==='flow-up'?-1:1);if(j<0||j>=p.flow.length)break;snapshot();[p.flow[i],p.flow[j]]=[p.flow[j],p.flow[i]];store();render();break;}
 case 'flow-remove':snapshot();p.flow.splice(+v,1);store();render();break;
 case 'flow-sort':snapshot();p.flow.sort((a,b)=>{const num=x=>Number(p.media[x.mediaId]?.name.match(/\d+/)?.[0]||999);return num(a)-num(b);});store();render();notify('Flow clips sorted numerically');break;
 case 'flow-clear':if(confirm('Clear only the Flow Clip Joiner sequence?')){snapshot();p.flow=[];store();render();}break;
 case 'flow-play':if(!flowEngine)return;if(flowEngine.playing){flowEngine.pause();button.textContent='▶';}else{await flowEngine.play();button.textContent='Ⅱ';}break;
 case 'flow-to-editor':{if(!p.flow.length)return notify('First import Flow clips');snapshot();const flow=tempFlowProject();p.clips=[...flow.clips];p.duration=flow.duration;p.ratio=flow.ratio;selectedClipId=null;store();setPage('editor');notify('Flow sequence copied to Manual Editor. Original Flow order preserved.');break;}
 case 'flow-export':if(p.flow.length)showExportDialog('flow');else notify('Add Flow clips first');break;
 case 'whisper-run':await runWhisper();break;
 case 'download-srt':exportText(serializeSrt(p.transcript),'CineZehn_Transcript.srt','application/x-subrip');break;
 case 'download-vtt':exportText(serializeVtt(p.transcript),'CineZehn_Transcript.vtt','text/vtt');break;
 case 'copy-transcript':copy(buildTranscriptChatGPT());break;
 case 'add-cue':snapshot();p.transcript.push({id:uid('cue'),start:0,end:2,text:'New subtitle'});store();render();break;
 case 'remove-cue':snapshot();p.transcript.splice(+v,1);store();render();break;
 case 'captions-to-timeline':{if(!p.transcript.length)return notify('Transcribe or import SRT first');snapshot();for(const cue of p.transcript)p.clips.push(clip('caption',cue.start,Math.max(.1,cue.end-cue.start),null,{name:'Transcript',track:3,text:cue.text,style:'Karaoke Yellow',motion:'None',fontSize:44,y:.79}));store();setPage('editor');notify(`${p.transcript.length} separate editable caption clips added`);break;}
 case 'generate-graphic':{const canvas=renderGraphicPNG($('#graphicType').value,$('#graphicText').value,$('#graphicColor').value);const blob=await new Promise(r=>canvas.toBlob(r,'image/png'));if(!blob)return notify('PNG generation failed');const id=await ingestFile(new File([blob],`CineZehn_${$('#graphicType').value.replace(/ /g,'_')}.png`,{type:'image/png'}));downloadData(blob,p.media[id].name);notify('Transparent PNG generated and added to Media Library');break;}
 case 'export-thumb':{const can=$('#thumbCanvas'),off=document.createElement('canvas');off.width=1280;off.height=720;off.getContext('2d').drawImage(can,0,0,1280,720);off.toBlob(blob=>downloadData(blob,'CineZehn_Thumbnail_1280x720.png'),'image/png');break;}
 case 'project-json':exportText(JSON.stringify(p,null,2),'CineZehn_Project_Backup.json','application/json');break;
 default:console.warn('Unknown action',a);
 }}catch(err){console.error(err);notify('Action error: '+err.message);}});
 document.body.addEventListener('change',e=>{const el=e.target;if(el.matches('input[type=file][data-ingest]')){onFiles(el);return;}
 if(el.dataset.slotPrompt!==undefined||el.dataset.slotField||el.dataset.slotToggle||el.dataset.extraToggle!==undefined||el.dataset.extraPrompt!==undefined||el.dataset.extraMotion!==undefined||el.dataset.overlayToggle!==undefined||el.dataset.overlayPrompt!==undefined||el.dataset.overlayMotion!==undefined){slotSet(el,el.type==='checkbox'?el.checked:el.value);if(el.type==='checkbox')render();return;}
 if(el.dataset.clip){updateClip(el);return;}
 if(el.dataset.field){const key=el.dataset.field;snapshot();p[key]=el.type==='number'?Number(el.value):el.value;if(key==='ratio')p.assets.forEach(a=>a.prompt=a.prompt.replace(/\b(9:16|16:9|1:1|4:5)\b/,p.ratio));store();render();return;}
 if(el.dataset.cueTime){const c=p.transcript[+el.dataset.cueIndex],n=seconds(el.value);if(n!==null){c[el.dataset.cueTime]=n;store();}else notify('Invalid time format');return;}
 if(el.dataset.cueText!==undefined){p.transcript[+el.dataset.cueText].text=el.value;store();return;}
 if(el.id==='planCount'){const row=$('#customCountRow');row?.classList.toggle('hide',el.value!=='Custom');return;}
 if(el.id==='themeSetting'){themeChange(el.value);return;}
 if(el.id==='whisperMedia'){selectedMediaId=el.value;return;}
 if(el.id==='whisperLang'){sessionStorage.setItem('whisper_lang',el.value);return;}
 if(el.id==='flowRatio'){p.flowRatio=el.value;store();render();return;}
 if(el.id==='thumbRatio'){const c=$('#thumbCanvas');if(el.value==='9:16'){c.width=360;c.height=640;}else{c.width=640;c.height=360;}drawThumbnail();return;}
 });
 document.body.addEventListener('input',e=>{const el=e.target;if(el.id==='seekBar')engine?.seek(Number(el.value));if(el.id==='flowSeek')flowEngine?.seek(Number(el.value));if(el.id==='timelineZoom'){timelineScale=+el.value;const t=engine?.t||0;render();engine?.seek(t);}
 if(el.id==='thumbTitle'){thumbnailTitle=el.value;drawThumbnail();}
 if(el.id==='masterPrompt'){p.masterPrompt=el.value;store();}
 if(el.dataset.slotPrompt!==undefined||el.dataset.extraPrompt!==undefined||el.dataset.overlayPrompt!==undefined||el.dataset.slotField||el.dataset.extraMotion!==undefined||el.dataset.overlayMotion!==undefined)slotSet(el,el.value);
 if(el.dataset.cueText!==undefined){p.transcript[+el.dataset.cueText].text=el.value;store();}
 });
 document.body.addEventListener('pointerdown',e=>{const clipEl=e.target.closest('.trackclip');if(!clipEl){if(e.target.closest('[data-seek-ruler]')){const r=e.target.getBoundingClientRect();engine?.seek(clamp((e.clientX-r.left)/timelineScale,0,p.duration));}return;}
 const id=clipEl.dataset.clipId,c=p.clips.find(x=>x.id===id);if(!c)return;selectedClipId=id;$$('.trackclip').forEach(el=>el.classList.toggle('selected',el.dataset.clipId===id));const prop=$('.inspector-panel');if(prop){prop.innerHTML=`<div class="between mb"><strong>Properties</strong><span class="pill">${esc(c.kind.toUpperCase())}</span></div>${inspectorView(c)}`;}
 const startX=e.clientX,originalStart=c.start,originalDuration=c.duration,originalIn=c.srcIn||0,action=e.target.dataset.handle||'move',trackBody=clipEl.closest('[data-drop-track]');let changed=false;const pointerId=e.pointerId;
 clipEl.setPointerCapture?.(pointerId);
 const move=ev=>{const delta=(ev.clientX-startX)/timelineScale;if(Math.abs(delta)<.05)return;changed=true;if(action==='move'){c.start=clamp(originalStart+delta,0,p.duration-.1);}else if(action==='left'){const d=clamp(delta,-originalStart,originalDuration-.15);c.start=originalStart+d;c.duration=originalDuration-d;c.srcIn=Math.max(0,originalIn+d*(c.speed||1));}else if(action==='right'){c.duration=clamp(originalDuration+delta,.15,p.duration-originalStart);}clipEl.style.left=c.start*timelineScale+'px';clipEl.style.width=Math.max(13,c.duration*timelineScale)+'px';engine?.draw();};
 const up=ev=>{clipEl.removeEventListener('pointermove',move);clipEl.removeEventListener('pointerup',up);clipEl.removeEventListener('pointercancel',up);try{clipEl.releasePointerCapture(pointerId);}catch{}if(changed){const prev={...c,start:originalStart,duration:originalDuration,srcIn:originalIn};undoStack.push(JSON.stringify({...p,clips:p.clips.map(x=>x.id===c.id?prev:x)}));if(undoStack.length>35)undoStack.shift();redoStack=[];store();render();}};
 clipEl.addEventListener('pointermove',move);clipEl.addEventListener('pointerup',up);clipEl.addEventListener('pointercancel',up);
 });
 document.body.addEventListener('dragstart',e=>{const item=e.target.closest('[data-media]');if(item)e.dataTransfer.setData('text/cinezehn-media',item.dataset.media);});
 document.body.addEventListener('dragover',e=>{if(e.target.closest('[data-drop-track]'))e.preventDefault();});
 document.body.addEventListener('drop',e=>{const tr=e.target.closest('[data-drop-track]');if(!tr)return;e.preventDefault();const id=e.dataTransfer.getData('text/cinezehn-media');if(!id||!p.media[id])return;addMediaClip(id);let c=currentClip();if(c){c.track=Number(tr.dataset.dropTrack);store();render();}});
 document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo();}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='y'){e.preventDefault();redo();}});
}
$('#goHome').onclick=()=>setPage('home');$('#themeToggle').onclick=()=>{themeChange(mode==='dark'?'light':'dark');notify(`${mode.toUpperCase()} theme selected`);};$('#openSettings').onclick=()=>setPage('settings');$$('.navlink').forEach(b=>b.addEventListener('click',()=>setPage(b.dataset.page)));
bindActions();render();
